let TOKEN = localStorage.getItem('docgen_token') || '';
let CURRENT_USER = null;
let DOC_TYPES = [];
let CMS = {};
let CURRENT_DOC = null; // full doc object being edited/previewed
let CURRENT_FORM_TYPE = null;
let gridDocumentsApi = null;
let gridUsersApi = null;
const $ = id => document.getElementById(id);
async function api(action, payload) {
  payload = payload || {};
  payload.action = action;
  payload.token = TOKEN;
  const res = await fetch(GAS_URL, {
    method: 'POST',
    redirect: 'follow',
    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    body: JSON.stringify(payload)
  });
  const json = await res.json();
  if (json.status === 'error') throw new Error(json.message);
  return json.data;
}
function toast(icon, title) {
  Swal.fire({ icon, title, toast: true, position: 'top-end', timer: 2200, showConfirmButton: false });
}
function loading(show) {
  if (show) Swal.fire({ title: 'Memproses...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });
  else Swal.close();
}
document.addEventListener('DOMContentLoaded', init);
async function init() {
  applyDarkModePref();
  bindStaticEvents();
  if (TOKEN) {
    try {
      CURRENT_USER = await api('validateToken', {});
      await afterLogin();
    } catch (e) {
      TOKEN = ''; localStorage.removeItem('docgen_token');
      showLogin();
    }
  } else {
    showLogin();
  }
}
function showLogin() {
  $('loginView').classList.remove('hidden');
  $('mainView').classList.add('hidden');
}
async function afterLogin() {
  $('loginView').classList.add('hidden');
  $('mainView').classList.remove('hidden');
  $('userBadge').textContent = CURRENT_USER.fullName + ' (' + CURRENT_USER.role + ')';
  try { CMS = await api('getCmsConfig', {}); applyCmsBranding(); } catch (e) {}
  buildSidebar();
  try { DOC_TYPES = await api('getDocumentTypes', {}); } catch (e) { DOC_TYPES = []; }
  populateDocTypeSelects();
  navigate('dashboard');
}
function applyCmsBranding() {
  if (CMS.siteTitle) { document.title = CMS.siteTitle; $('sideTitle').textContent = CMS.siteTitle; $('loginTitle').textContent = CMS.siteTitle; }
  if (CMS.logoUrl) {
    $('loginLogo').outerHTML = '<img id="loginLogo" src="' + CMS.logoUrl + '" class="w-14 h-14 mx-auto rounded-xl object-cover mb-3">';
  }
}
function applyDarkModePref() {
  const pref = localStorage.getItem('docgen_dark');
  if (pref === '1') document.documentElement.classList.add('dark');
}
function toggleDark() {
  document.documentElement.classList.toggle('dark');
  localStorage.setItem('docgen_dark', document.documentElement.classList.contains('dark') ? '1' : '0');
}
function bindStaticEvents() {
  $('btnLogin').onclick = doLogin;
  $('loginPassword').addEventListener('keydown', e => { if (e.key === 'Enter') doLogin(); });
  $('btnToggleDark').onclick = toggleDark;
  $('btnToggleDarkLogin').onclick = toggleDark;
  $('btnLogout').onclick = doLogout;
  $('btnHamburger').onclick = () => { $('sidebar').classList.toggle('-translate-x-full'); $('sidebarOverlay').classList.toggle('hidden'); };
  $('sidebarOverlay').onclick = () => { $('sidebar').classList.add('-translate-x-full'); $('sidebarOverlay').classList.add('hidden'); };
  $('btnNewDoc').onclick = () => openForm(null);
  $('btnCancelForm').onclick = () => navigate('documents');
  $('btnSaveDoc').onclick = () => saveDocument(false);
  $('btnPreviewDoc').onclick = () => saveDocument(true);
  $('filterDocType').onchange = loadDocumentsGrid;
  $('filterStatus').onchange = loadDocumentsGrid;
  $('btnBackFromPreview').onclick = () => navigate('documents');
  $('btnPrint').onclick = () => window.print();
  $('btnGenDocs').onclick = handleGenerateDocs;
  $('btnGenPdf').onclick = handleGeneratePdf;
  $('btnSubmitReview').onclick = () => docAction('submitForReview', 'Dokumen dikirim untuk review');
  $('btnApproveDoc').onclick = () => docAction('approveDocument', 'Dokumen disetujui');
  $('btnRejectDoc').onclick = () => docAction('rejectDocument', 'Dokumen ditolak');
  $('btnNewDocType').onclick = () => openDocTypeModal(null);
  $('btnCloseDocType').onclick = () => $('modalDocType').classList.add('hidden');
  $('btnSaveDocType').onclick = saveDocType;
  $('btnAddSection').onclick = () => addSectionRow(null);
  $('btnNewUser').onclick = () => openUserModal(null);
  $('btnCloseUser').onclick = () => $('modalUser').classList.add('hidden');
  $('btnSaveUser').onclick = saveUser;
  $('btnSaveSettings').onclick = saveSettings;
}
async function doLogin() {
  const username = $('loginUsername').value.trim();
  const password = $('loginPassword').value;
  if (!username || !password) return toast('warning', 'Isi username & password');
  loading(true);
  try {
    const data = await api('login', { username, password });
    TOKEN = data.token;
    localStorage.setItem('docgen_token', TOKEN);
    CURRENT_USER = data;
    loading(false);
    await afterLogin();
  } catch (e) {
    loading(false);
    toast('error', e.message);
  }
}
async function doLogout() {
  try { await api('logout', {}); } catch (e) {}
  TOKEN = ''; CURRENT_USER = null;
  localStorage.removeItem('docgen_token');
  showLogin();
}
const MENU = [
  { id: 'dashboard', label: '📊 Dashboard', roles: ['Admin', 'Editor', 'Viewer'] },
  { id: 'documents', label: '📄 Dokumen', roles: ['Admin', 'Editor', 'Viewer'] },
  { id: 'doctypes', label: '🧩 Jenis Dokumen (CMS)', roles: ['Admin'] },
  { id: 'users', label: '👤 Manajemen User', roles: ['Admin'] },
  { id: 'settings', label: '⚙️ Pengaturan', roles: ['Admin'] }
];
function buildSidebar() {
  const nav = $('sideNav');
  nav.innerHTML = '';
  MENU.filter(m => m.roles.includes(CURRENT_USER.role)).forEach(m => {
    const btn = document.createElement('button');
    btn.className = 'w-full text-left px-3 py-2 rounded-lg hover:bg-indigo-50 dark:hover:bg-gray-700 font-medium';
    btn.textContent = m.label;
    btn.onclick = () => navigate(m.id);
    btn.dataset.nav = m.id;
    nav.appendChild(btn);
  });
}
const VIEW_TITLES = { dashboard: 'Dashboard', documents: 'Daftar Dokumen', form: 'Form Dokumen', preview: 'Pratinjau Dokumen', doctypes: 'Jenis Dokumen (CMS)', users: 'Manajemen User', settings: 'Pengaturan' };
function navigate(view) {
  ['dashboard', 'documents', 'form', 'preview', 'doctypes', 'users', 'settings'].forEach(v => {
    $('view-' + v).classList.toggle('hidden', v !== view);
  });
  $('pageTitle').textContent = VIEW_TITLES[view] || '';
  document.querySelectorAll('[data-nav]').forEach(b => b.classList.toggle('bg-indigo-100', b.dataset.nav === view));
  $('sidebar').classList.add('-translate-x-full'); $('sidebarOverlay').classList.add('hidden');
  if (view === 'dashboard') loadDashboard();
  if (view === 'documents') loadDocumentsGrid();
  if (view === 'doctypes') loadDocTypeList();
  if (view === 'users') loadUsersGrid();
  if (view === 'settings') loadSettingsForm();
}
async function loadDashboard() {
  loading(true);
  try {
    const stats = await api('getDashboardStats', {});
    loading(false);
    $('statCards').innerHTML = [
      ['Total Dokumen', stats.total, 'bg-indigo-600'],
      ['Draft', stats.byStatus.Draft || 0, 'bg-gray-500'],
      ['Review', stats.byStatus.Review || 0, 'bg-amber-500'],
      ['Approved', (stats.byStatus.Approved || 0) + (stats.byStatus.Released || 0), 'bg-emerald-600']
    ].map(([label, val, color]) => `<div class="rounded-xl p-4 text-white ${color}"><div class="text-2xl font-bold">${val}</div><div class="text-xs opacity-90">${label}</div></div>`).join('');
    AgCharts.create({
      container: $('chartByStatus'),
      title: { text: 'Dokumen per Status' },
      data: Object.keys(stats.byStatus).map(k => ({ status: k, count: stats.byStatus[k] })),
      series: [{ type: 'pie', angleKey: 'count', labelKey: 'status' }]
    });
    AgCharts.create({
      container: $('chartByType'),
      title: { text: 'Dokumen per Jenis' },
      data: Object.keys(stats.byType).map(k => ({ type: k, count: stats.byType[k] })),
      series: [{ type: 'bar', xKey: 'type', yKey: 'count' }]
    });
    $('recentDocs').innerHTML = stats.recent.map(d =>
      `<div class="py-2 flex justify-between"><span>${d.docNumber} — ${d.title}</span><span class="text-xs px-2 py-0.5 rounded-full ${statusBadge(d.status)}">${d.status}</span></div>`
    ).join('') || '<div class="text-gray-400 text-xs">Belum ada dokumen</div>';
  } catch (e) { loading(false); toast('error', e.message); }
}
function statusBadge(status) {
  return { Draft: 'bg-gray-200 text-gray-700', Review: 'bg-amber-100 text-amber-700', Approved: 'bg-emerald-100 text-emerald-700',
    Rejected: 'bg-red-100 text-red-700', Released: 'bg-blue-100 text-blue-700' }[status] || 'bg-gray-200';
}
function populateDocTypeSelects() {
  const opts = DOC_TYPES.map(t => `<option value="${t.id}">${t.name}</option>`).join('');
  $('filterDocType').innerHTML = '<option value="">Semua Jenis</option>' + opts;
  $('formDocType').innerHTML = '<option value="">-- Pilih Jenis Dokumen --</option>' + opts;
}
async function loadDocumentsGrid() {
  loading(true);
  try {
    const docs = await api('getDocuments', { docTypeId: $('filterDocType').value, status: $('filterStatus').value });
    loading(false);
    const columnDefs = [
      { field: 'docNumber', headerName: 'No. Dokumen', width: 160 },
      { field: 'title', headerName: 'Judul', flex: 1 },
      { field: 'docTypeId', headerName: 'Jenis', width: 160, valueFormatter: p => (DOC_TYPES.find(t => t.id === p.value) || {}).name || p.value },
      { field: 'status', headerName: 'Status', width: 120 },
      { field: 'createdByName', headerName: 'Dibuat oleh', width: 140 },
      { field: 'updatedAt', headerName: 'Diperbarui', width: 160, valueFormatter: p => p.value ? new Date(p.value).toLocaleString('id-ID') : '' },
      { headerName: 'Aksi', width: 160, cellRenderer: p => {
          const div = document.createElement('div'); div.className = 'flex gap-1 py-1';
          const btnView = document.createElement('button'); btnView.textContent = '👁'; btnView.className = 'px-2 rounded bg-gray-200';
          btnView.onclick = () => openPreview(p.data.id);
          div.appendChild(btnView);
          if (CURRENT_USER.role !== 'Viewer') {
            const btnEdit = document.createElement('button'); btnEdit.textContent = '✏️'; btnEdit.className = 'px-2 rounded bg-blue-100';
            btnEdit.onclick = () => openForm(p.data.id);
            div.appendChild(btnEdit);
            const btnDel = document.createElement('button'); btnDel.textContent = '🗑'; btnDel.className = 'px-2 rounded bg-red-100';
            btnDel.onclick = () => deleteDocument(p.data.id);
            div.appendChild(btnDel);
          }
          return div;
        } }
    ];
    if (gridDocumentsApi) gridDocumentsApi.destroy();
    gridDocumentsApi = agGrid.createGrid($('gridDocuments'), { columnDefs, rowData: docs, pagination: true, paginationPageSize: 15 });
  } catch (e) { loading(false); toast('error', e.message); }
}
async function deleteDocument(id) {
  const conf = await Swal.fire({ title: 'Hapus dokumen ini?', icon: 'warning', showCancelButton: true, confirmButtonText: 'Hapus' });
  if (!conf.isConfirmed) return;
  loading(true);
  try { await api('deleteDocument', { id }); loading(false); toast('success', 'Dihapus'); loadDocumentsGrid(); }
  catch (e) { loading(false); toast('error', e.message); }
}
function openForm(docId) {
  CURRENT_FORM_TYPE = null;
  $('formTitle').value = ''; $('formProject').value = ''; $('formDocType').value = ''; $('formSections').innerHTML = '';
  CURRENT_DOC = docId ? { id: docId } : null;
  navigate('form');
  $('formDocType').onchange = () => renderFormSections($('formDocType').value, {});
  if (docId) loadDocForEdit(docId);
}
async function loadDocForEdit(docId) {
  loading(true);
  try {
    const doc = await api('getDocument', { id: docId });
    loading(false);
    CURRENT_DOC = doc;
    $('formTitle').value = doc.title;
    $('formProject').value = doc.projectName;
    $('formDocType').value = doc.docTypeId;
    renderFormSections(doc.docTypeId, doc.data);
  } catch (e) { loading(false); toast('error', e.message); }
}
function renderFormSections(docTypeId, data) {
  const type = DOC_TYPES.find(t => t.id === docTypeId);
  CURRENT_FORM_TYPE = type;
  const container = $('formSections'); container.innerHTML = '';
  if (!type) return;
  type.sections.forEach(sec => {
    const wrap = document.createElement('div');
    wrap.className = 'bg-white dark:bg-gray-800 rounded-xl p-4 shadow';
    const label = `<label class="text-sm font-semibold block mb-1">${sec.label}${sec.required ? ' *' : ''}</label>`;
    let field = '';
    const val = data ? data[sec.id] : undefined;
    if (sec.type === 'textarea' || sec.type === 'richtext') {
      field = `<textarea data-field="${sec.id}" rows="4" class="w-full px-3 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600 text-sm">${val || ''}</textarea>`;
    } else if (sec.type === 'date') {
      field = `<input type="date" data-field="${sec.id}" value="${val || ''}" class="w-full px-3 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600 text-sm">`;
    } else if (sec.type === 'select') {
      field = `<select data-field="${sec.id}" class="w-full px-3 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600 text-sm">` +
        (sec.options || []).map(o => `<option ${val === o ? 'selected' : ''}>${o}</option>`).join('') + `</select>`;
    } else if (sec.type === 'signature') {
      const sig = val || {};
      field = `<div class="grid grid-cols-3 gap-2">
        <input placeholder="Nama" data-field="${sec.id}" data-sub="name" value="${sig.name || ''}" class="px-2 py-1.5 rounded-lg border dark:bg-gray-700 dark:border-gray-600 text-sm">
        <input placeholder="Jabatan" data-field="${sec.id}" data-sub="role" value="${sig.role || ''}" class="px-2 py-1.5 rounded-lg border dark:bg-gray-700 dark:border-gray-600 text-sm">
        <input type="date" data-field="${sec.id}" data-sub="date" value="${sig.date || ''}" class="px-2 py-1.5 rounded-lg border dark:bg-gray-700 dark:border-gray-600 text-sm"></div>`;
    } else if (sec.type === 'table') {
      const rows = Array.isArray(val) && val.length ? val : [{}];
      field = `<div data-field="${sec.id}" data-table="1"><table class="w-full text-xs border"><thead><tr>${
        (sec.columns || []).map(c => `<th class="border px-1 py-1 bg-gray-50 dark:bg-gray-700">${c.label}</th>`).join('')
      }<th class="border px-1"></th></tr></thead><tbody>${
        rows.map(r => tableRowHtml(sec, r)).join('')
      }</tbody></table><button type="button" class="mt-1 text-xs px-2 py-1 bg-gray-200 dark:bg-gray-600 rounded" onclick="addTableRow('${sec.id}')">+ Baris</button></div>`;
    } else {
      field = `<input data-field="${sec.id}" value="${val || ''}" class="w-full px-3 py-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600 text-sm">`;
    }
    wrap.innerHTML = label + field;
    container.appendChild(wrap);
  });
}
function tableRowHtml(sec, row) {
  row = row || {};
  return `<tr>${(sec.columns || []).map(c => `<td class="border px-1"><input value="${row[c.id] || ''}" data-col="${c.id}" class="w-full px-1 py-1 text-xs bg-transparent"></td>`).join('')}<td class="border px-1"><button type="button" class="text-red-500 text-xs" onclick="this.closest('tr').remove()">✕</button></td></tr>`;
}
function addTableRow(secId) {
  const sec = CURRENT_FORM_TYPE.sections.find(s => s.id === secId);
  const tbody = document.querySelector(`[data-field="${secId}"] tbody`);
  tbody.insertAdjacentHTML('beforeend', tableRowHtml(sec, {}));
}
function collectFormData() {
  const data = {};
  if (!CURRENT_FORM_TYPE) return data;
  CURRENT_FORM_TYPE.sections.forEach(sec => {
    if (sec.type === 'table') {
      const wrap = document.querySelector(`[data-field="${sec.id}"][data-table="1"]`);
      const rows = [...wrap.querySelectorAll('tbody tr')].map(tr => {
        const obj = {};
        tr.querySelectorAll('input[data-col]').forEach(inp => obj[inp.dataset.col] = inp.value);
        return obj;
      }).filter(r => Object.values(r).some(v => v));
      data[sec.id] = rows;
    } else if (sec.type === 'signature') {
      const obj = {};
      document.querySelectorAll(`[data-field="${sec.id}"][data-sub]`).forEach(inp => obj[inp.dataset.sub] = inp.value);
      data[sec.id] = obj;
    } else {
      const el = document.querySelector(`[data-field="${sec.id}"]:not([data-sub]):not([data-table])`);
      data[sec.id] = el ? el.value : '';
    }
  });
  return data;
}
async function saveDocument(thenPreview) {
  if (!$('formDocType').value) return toast('warning', 'Pilih jenis dokumen');
  if (!$('formTitle').value.trim()) return toast('warning', 'Isi judul dokumen');
  const payload = { docTypeId: $('formDocType').value, title: $('formTitle').value, projectName: $('formProject').value, data: collectFormData() };
  loading(true);
  try {
    let id;
    if (CURRENT_DOC && CURRENT_DOC.id) { payload.id = CURRENT_DOC.id; await api('updateDocument', payload); id = CURRENT_DOC.id; }
    else { const res = await api('createDocument', payload); id = res.id; }
    loading(false);
    toast('success', 'Dokumen tersimpan');
    if (thenPreview) openPreview(id); else navigate('documents');
  } catch (e) { loading(false); toast('error', e.message); }
}
async function openPreview(id) {
  loading(true);
  try {
    const doc = await api('getDocument', { id });
    loading(false);
    CURRENT_DOC = doc;
    renderPreview(doc);
    navigate('preview');
    const isAdmin = CURRENT_USER.role === 'Admin';
    $('btnSubmitReview').classList.toggle('hidden', !(doc.status === 'Draft' && CURRENT_USER.role !== 'Viewer'));
    $('btnApproveDoc').classList.toggle('hidden', !(doc.status === 'Review' && isAdmin));
    $('btnRejectDoc').classList.toggle('hidden', !(doc.status === 'Review' && isAdmin));
  } catch (e) { loading(false); toast('error', e.message); }
}
function renderPreview(doc) {
  const type = doc.docType || {};
  const layout = type.layout || {};
  const font = (layout.font && layout.font.family) || 'Arial';
  const fontSize = (layout.font && layout.font.size) || 11;
  const margin = layout.margin || { top: 2.5, bottom: 2.5, left: 2.5, right: 2.5 };
  const el = $('printArea');
  el.style.fontFamily = font;
  el.style.fontSize = fontSize + 'pt';
  el.style.padding = `${margin.top}cm ${margin.right}cm ${margin.bottom}cm ${margin.left}cm`;
  let html = '';
  if (layout.header && layout.header.show) {
    html += `<div class="text-xs text-gray-500 border-b pb-2 mb-4 flex justify-between"><span>${(layout.header.text || '').replace('{companyName}', CMS.companyName || '')}</span><span>${doc.docNumber}</span></div>`;
  }
  const titleStyle = layout.titleStyle || {};
  html += `<h1 style="text-align:${titleStyle.align || 'center'};font-weight:${titleStyle.bold ? '700' : '400'};font-size:${(titleStyle.size || 16)}pt" class="mb-1">${(doc.title || '').toUpperCase()}</h1>`;
  html += `<p class="text-center text-xs mb-1">No. Dokumen: ${doc.docNumber}</p>`;
  if (doc.projectName) html += `<p class="text-center text-xs mb-4">Proyek: ${doc.projectName}</p>`;
  (type.sections || []).forEach(sec => {
    html += `<h3 class="font-bold mt-4 mb-1" style="font-size:${fontSize + 1}pt">${sec.label}</h3>`;
    const val = doc.data ? doc.data[sec.id] : undefined;
    if (sec.type === 'table') {
      const rows = Array.isArray(val) ? val : [];
      html += `<table class="w-full border text-xs mb-2"><thead><tr>${(sec.columns || []).map(c => `<th class="border px-2 py-1 bg-gray-50">${c.label}</th>`).join('')}</tr></thead><tbody>${
        rows.map(r => `<tr>${(sec.columns || []).map(c => `<td class="border px-2 py-1">${r[c.id] || ''}</td>`).join('')}</tr>`).join('') || `<tr><td class="border px-2 py-1 text-gray-400" colspan="${(sec.columns || []).length}">-</td></tr>`
      }</tbody></table>`;
    } else if (sec.type === 'signature') {
      const sig = val || {};
      html += `<div class="text-xs space-y-4 mt-2"><p>Nama: ${sig.name || '________________'}</p><p>Jabatan: ${sig.role || '________________'}</p><p>Tanggal: ${sig.date || '________________'}</p><div class="mt-8">Tanda tangan:</div><div class="border-b w-48 mt-8"></div></div>`;
    } else {
      html += `<p class="whitespace-pre-line" style="font-size:${fontSize}pt">${val || '-'}</p>`;
    }
  });
  if (layout.footer && layout.footer.show) {
    html += `<div class="text-[10px] text-gray-400 border-t mt-8 pt-2 flex justify-between"><span>${layout.footer.text || ''}</span><span>Status: ${doc.status}</span></div>`;
  }
  el.innerHTML = html;
}
async function handleGenerateDocs() {
  loading(true);
  try { const res = await api('generateDoc', { id: CURRENT_DOC.id }); loading(false); toast('success', 'Google Docs dibuat'); window.open(res.url, '_blank'); }
  catch (e) { loading(false); toast('error', e.message); }
}
async function handleGeneratePdf() {
  loading(true);
  try { const res = await api('exportPdf', { id: CURRENT_DOC.id }); loading(false); toast('success', 'PDF siap diunduh'); window.open(res.downloadUrl, '_blank'); }
  catch (e) { loading(false); toast('error', e.message); }
}
async function docAction(action, msg) {
  loading(true);
  try { await api(action, { id: CURRENT_DOC.id }); loading(false); toast('success', msg); openPreview(CURRENT_DOC.id); }
  catch (e) { loading(false); toast('error', e.message); }
}
let EDIT_SECTIONS = [];
async function loadDocTypeList() {
  loading(true);
  try {
    DOC_TYPES = await api('getDocumentTypes', {});
    loading(false);
    populateDocTypeSelects();
    $('docTypeList').innerHTML = DOC_TYPES.map(t => `
      <div class="bg-white dark:bg-gray-800 rounded-xl p-4 shadow">
        <div class="flex justify-between items-start">
          <div><div class="font-bold text-sm">${t.name}</div><div class="text-xs text-gray-500">${t.code} • ${t.category} • ${t.sections.length} field</div></div>
          <span class="text-xs px-2 py-0.5 rounded-full ${t.isActive ? 'bg-emerald-100 text-emerald-700' : 'bg-gray-200 text-gray-500'}">${t.isActive ? 'Aktif' : 'Nonaktif'}</span>
        </div>
        <div class="flex gap-2 mt-3">
          <button class="text-xs px-3 py-1 bg-blue-100 rounded-lg" onclick="openDocTypeModal('${t.id}')">Edit</button>
          <button class="text-xs px-3 py-1 bg-red-100 rounded-lg" onclick="deleteDocType('${t.id}')">Hapus</button>
        </div>
      </div>`).join('') || '<p class="text-sm text-gray-400">Belum ada jenis dokumen</p>';
  } catch (e) { loading(false); toast('error', e.message); }
}
function openDocTypeModal(id) {
  const t = id ? DOC_TYPES.find(x => x.id === id) : null;
  $('modalDocType').dataset.editId = id || '';
  $('dtCode').value = t ? t.code : '';
  $('dtName').value = t ? t.name : '';
  $('dtCategory').value = t ? t.category : '';
  $('dtNumbering').value = t ? t.numberingFormat : '';
  const layout = t ? t.layout : { pageSize: 'A4', font: { family: 'Arial', size: 11 }, margin: { top: 2.5, bottom: 2.5, left: 2.5, right: 2.5 }, header: { show: true, text: '{companyName}' }, footer: { show: true, text: '' } };
  $('ltPageSize').value = layout.pageSize || 'A4';
  $('ltFont').value = (layout.font || {}).family || 'Arial';
  $('ltFontSize').value = (layout.font || {}).size || 11;
  $('ltMargin').value = (layout.margin || {}).top || 2.5;
  $('ltHeaderText').value = (layout.header || {}).text || '';
  $('ltFooterText').value = (layout.footer || {}).text || '';
  EDIT_SECTIONS = t ? JSON.parse(JSON.stringify(t.sections)) : [];
  renderSectionBuilder();
  $('modalDocType').classList.remove('hidden');
}
function renderSectionBuilder() {
  $('sectionBuilder').innerHTML = '';
  EDIT_SECTIONS.forEach((sec, idx) => addSectionRow(sec, idx));
}
function addSectionRow(sec, idx) {
  if (!sec) { sec = { id: 'field' + (EDIT_SECTIONS.length + 1), label: '', type: 'textarea', required: false }; EDIT_SECTIONS.push(sec); idx = EDIT_SECTIONS.length - 1; }
  const row = document.createElement('div');
  row.className = 'flex gap-2 items-center bg-gray-50 dark:bg-gray-700 p-2 rounded-lg';
  row.innerHTML = `
    <input value="${sec.label}" placeholder="Label field" class="flex-1 px-2 py-1 rounded border text-xs dark:bg-gray-600" onchange="EDIT_SECTIONS[${idx}].label=this.value">
    <select class="px-2 py-1 rounded border text-xs dark:bg-gray-600" onchange="EDIT_SECTIONS[${idx}].type=this.value">
      ${['text', 'textarea', 'richtext', 'date', 'select', 'table', 'signature'].map(o => `<option ${sec.type === o ? 'selected' : ''}>${o}</option>`).join('')}
    </select>
    <label class="text-xs flex items-center gap-1"><input type="checkbox" ${sec.required ? 'checked' : ''} onchange="EDIT_SECTIONS[${idx}].required=this.checked"> Wajib</label>
    <button class="text-red-500 text-xs" onclick="EDIT_SECTIONS.splice(${idx},1);renderSectionBuilder()">✕</button>`;
  $('sectionBuilder').appendChild(row);
}
async function saveDocType() {
  const id = $('modalDocType').dataset.editId;
  EDIT_SECTIONS.forEach(s => { if (!s.id) s.id = 'field_' + Math.random().toString(36).slice(2, 7); });
  const payload = {
    code: $('dtCode').value, name: $('dtName').value, category: $('dtCategory').value,
    numberingFormat: $('dtNumbering').value, sections: EDIT_SECTIONS,
    layout: {
      pageSize: $('ltPageSize').value,
      font: { family: $('ltFont').value, size: Number($('ltFontSize').value) },
      margin: { top: Number($('ltMargin').value), bottom: Number($('ltMargin').value), left: Number($('ltMargin').value), right: Number($('ltMargin').value) },
      header: { show: true, text: $('ltHeaderText').value },
      footer: { show: true, text: $('ltFooterText').value },
      titleStyle: { align: 'center', bold: true, size: 16 }
    },
    isActive: true
  };
  if (!payload.code || !payload.name) return toast('warning', 'Kode dan nama wajib diisi');
  loading(true);
  try {
    if (id) { payload.id = id; await api('updateDocumentType', payload); } else { await api('createDocumentType', payload); }
    loading(false);
    toast('success', 'Jenis dokumen tersimpan');
    $('modalDocType').classList.add('hidden');
    loadDocTypeList();
  } catch (e) { loading(false); toast('error', e.message); }
}
async function deleteDocType(id) {
  const conf = await Swal.fire({ title: 'Hapus jenis dokumen ini?', icon: 'warning', showCancelButton: true });
  if (!conf.isConfirmed) return;
  loading(true);
  try { await api('deleteDocumentType', { id }); loading(false); toast('success', 'Dihapus'); loadDocTypeList(); }
  catch (e) { loading(false); toast('error', e.message); }
}
async function loadUsersGrid() {
  loading(true);
  try {
    const users = await api('getUsers', {});
    loading(false);
    const columnDefs = [
      { field: 'fullName', headerName: 'Nama', flex: 1 },
      { field: 'username', headerName: 'Username', width: 140 },
      { field: 'email', headerName: 'Email', width: 180 },
      { field: 'role', headerName: 'Role', width: 100 },
      { field: 'isActive', headerName: 'Aktif', width: 80, valueFormatter: p => p.value ? '✅' : '❌' },
      { headerName: 'Aksi', width: 100, cellRenderer: p => {
          const btn = document.createElement('button'); btn.textContent = '✏️ Edit'; btn.className = 'text-xs px-2 py-1 bg-blue-100 rounded';
          btn.onclick = () => openUserModal(p.data); return btn;
        } }
    ];
    if (gridUsersApi) gridUsersApi.destroy();
    gridUsersApi = agGrid.createGrid($('gridUsers'), { columnDefs, rowData: users, pagination: true });
  } catch (e) { loading(false); toast('error', e.message); }
}
function openUserModal(user) {
  $('modalUser').dataset.editId = user ? user.id : '';
  $('uFullName').value = user ? user.fullName : '';
  $('uUsername').value = user ? user.username : '';
  $('uEmail').value = user ? user.email : '';
  $('uPassword').value = '';
  $('uRole').value = user ? user.role : 'Viewer';
  $('uActive').checked = user ? !!user.isActive : true;
  $('modalUser').classList.remove('hidden');
}
async function saveUser() {
  const id = $('modalUser').dataset.editId;
  const payload = { fullName: $('uFullName').value, username: $('uUsername').value, email: $('uEmail').value, role: $('uRole').value, isActive: $('uActive').checked };
  if ($('uPassword').value) payload.password = $('uPassword').value;
  if (!payload.fullName || !payload.username) return toast('warning', 'Nama dan username wajib diisi');
  loading(true);
  try {
    if (id) { payload.id = id; await api('updateUser', payload); } else { await api('createUser', payload); }
    loading(false); toast('success', 'User tersimpan'); $('modalUser').classList.add('hidden'); loadUsersGrid();
  } catch (e) { loading(false); toast('error', e.message); }
}
async function loadSettingsForm() {
  loading(true);
  try {
    CMS = await api('getCmsConfig', {});
    loading(false);
    $('cfgSiteTitle').value = CMS.siteTitle || '';
    $('cfgCompanyName').value = CMS.companyName || '';
    $('cfgLogoUrl').value = CMS.logoUrl || '';
    $('cfgEmailNotif').checked = CMS.emailNotifEnabled === 'true';
  } catch (e) { loading(false); toast('error', e.message); }
}
async function saveSettings() {
  loading(true);
  try {
    await api('updateCmsConfig', { config: {
      siteTitle: $('cfgSiteTitle').value, companyName: $('cfgCompanyName').value,
      logoUrl: $('cfgLogoUrl').value, emailNotifEnabled: String($('cfgEmailNotif').checked)
    } });
    loading(false); toast('success', 'Pengaturan tersimpan'); applyCmsBranding();
  } catch (e) { loading(false); toast('error', e.message); }
}
